cssCode:
.prog-wrap {
  width: 80%; max-width: 300px; height: 50px; background: #222; border-radius: 25px;
  position: relative; overflow: hidden; cursor: pointer; border: 2px solid #444;
  box-shadow: inset 0 5px 10px rgba(0,0,0,0.5);
}
.prog-bar {
  width: 0%; height: 100%; background: linear-gradient(90deg, #ff007f, #7f00ff);
  transition: width 2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  box-shadow: 0 0 20px rgba(255,0,127,0.5);
}
.prog-wrap.fill .prog-bar { width: 100%; }
.prog-text {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-family: sans-serif; font-weight: bold; font-size: 14px;
  letter-spacing: 2px;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

c.innerHTML = `
  <div class="prog-wrap" id="progBox">
    <div class="prog-bar"></div>
    <div class="prog-text" id="progTxt">TAP TO COMPLETE</div>
  </div>
`;

const box = document.getElementById('progBox');
const txt = document.getElementById('progTxt');

box.addEventListener('click', () => {
  box.classList.toggle('fill');
  if(box.classList.contains('fill')) {
    txt.innerText = 'COMPLETED! 🎉';
  } else {
    txt.innerText = 'TAP TO COMPLETE';
  }
});
